/** A variable font at each weight in [weights] with the variation [axes]; no `wght` among them. */
private fun variableFontFamily(
  @FontRes font: Int,
  weights: List<Int>,
  vararg axes: FontVariation.Setting,
): FontFamily =
  FontFamily(
    weights.map { weight ->
      Font(
        font,
        FontWeight(weight),
        variationSettings =
          FontVariation.Settings(
            FontWeight(weight),
            FontStyle.Normal,
            *axes,
          ),
      )
    },
  )

private val FrauncesDisplayLarge =
  variableFontFamily(
    R.font.fraunces,
    listOf(400, 500, 700),
    FontVariation.opticalSizing(72.sp),
    FontVariation.Setting("SOFT", 50f),
  )

