@Composable
fun TonightsPlateTheme(
  darkTheme: Boolean = isSystemInDarkTheme(),
  content: @Composable () -> Unit,
) {
  MaterialExpressiveTheme(
    colorScheme =
      rememberDynamicColorScheme(
        seedColor = SeedColor,
        isDark = darkTheme,
        style = PaletteStyle.Expressive,
        contrastLevel = 0.0,
        specVersion = ColorSpec.SpecVersion.SPEC_2025,
      ),
    typography = AppTypography,
    shapes = AppShapes,
    motionScheme = MotionScheme.expressive(),
    content = content,
  )
}

@Serializable private data object PlatesRoute : NavKey

@Serializable private data object PlateDetailRoute : NavKey

@Composable
fun TonightsPlateApp() {
  TonightsPlateTheme {
    val backStack = rememberNavBackStack(PlatesRoute)
    val listDetailStrategy = rememberListDetailSceneStrategy<NavKey>()
    NavDisplay(
      backStack = backStack,
      onBack = { backStack.removeLastOrNull() },
      sceneStrategies = listOf(listDetailStrategy),
      entryProvider =
        entryProvider {
          entry<PlatesRoute>(metadata = ListDetailSceneStrategy.listPane()) {
            PlatesScreen(onNavigateToPlateDetail = { backStack.add(PlateDetailRoute) })
          }
          entry<PlateDetailRoute>(metadata = ListDetailSceneStrategy.detailPane()) {
            PlateDetailScreen(onBack = { backStack.removeLastOrNull() })
          }
        },
    )
  }
}

@Composable
fun PlatesScreen(
  modifier: Modifier = Modifier,
  plates: List<Plate> = PlatesSample.plates,
  onNavigateToPlateDetail: () -> Unit = {},
) {
  var showNewSheet by remember { mutableStateOf(false) }
  val scrollBehavior = TopAppBarDefaults.exitUntilCollapsedScrollBehavior()
  Scaffold(
    modifier = modifier.nestedScroll(scrollBehavior.nestedScrollConnection),
    topBar = {
      LargeFlexibleTopAppBar(title = { Text("Tonight's plate") }, scrollBehavior = scrollBehavior)
    },
    floatingActionButton = {
      MediumExtendedFloatingActionButton(
        onClick = { showNewSheet = true },
        icon = {
          Icon(
            painterResource(R.drawable.add),
            contentDescription = null,
            modifier = Modifier.size(FloatingActionButtonDefaults.MediumIconSize),
          )
        },
        text = { Text("New plate") },
      )
    },
  ) { innerPadding ->
    Column(
      modifier = Modifier.fillMaxSize().padding(innerPadding).padding(16.dp),
      verticalArrangement = Arrangement.spacedBy(ListItemDefaults.SegmentedGap),
    ) {
      plates.forEachIndexed { index, plate ->
        SegmentedListItem(
          onClick = { onNavigateToPlateDetail() },
          shapes = ListItemDefaults.segmentedShapes(index, plates.size),
          modifier = Modifier.fillMaxWidth(),
          colors = ListItemDefaults.segmentedColors(),
          supportingContent = { Text(plate.time) },
        ) {
          Text(plate.name)
        }
      }
    }
  }
  if (showNewSheet) {
    ModalBottomSheet(onDismissRequest = { showNewSheet = false }) {
      Text("Add a plate", style = MaterialTheme.typography.headlineSmall)
      TextButton(onClick = { showNewSheet = false }) { Text("Not now") }
    }
  }
}

