@Composable
fun PlateDetailScreen(
  modifier: Modifier = Modifier,
  plate: PlateDetailPlate = PlateDetailSample.plate,
  onBack: () -> Unit = {},
) {
  Scaffold(
    modifier = modifier,
    topBar = {
      TopAppBar(
        title = { Text(plate.name) },
        navigationIcon = {
          IconButton(
            onClick = { onBack() },
            colors =
              IconButtonDefaults.iconButtonColors(
                contentColor = MaterialTheme.colorScheme.onSurfaceVariant,
              ),
          ) {
            Icon(painterResource(R.drawable.arrow_back), contentDescription = "Back")
          }
        },
      )
    },
  ) { innerPadding ->
    Column(
      modifier = Modifier.fillMaxSize().padding(innerPadding).padding(16.dp),
      verticalArrangement = Arrangement.spacedBy(16.dp),
    ) {
      Text(
        plate.name,
        color = MaterialTheme.colorScheme.onSurface,
        style = MaterialTheme.typography.displaySmallEmphasized,
      )
      Text(
        plate.description,
        overflow = TextOverflow.Ellipsis,
        maxLines = 3,
        style = MaterialTheme.typography.bodyLarge,
      )
      Button(
        onClick = {},
        modifier = Modifier.heightIn(min = ButtonDefaults.LargeContainerHeight),
        shapes = ButtonDefaults.shapesFor(ButtonDefaults.LargeContainerHeight),
        contentPadding = ButtonDefaults.contentPaddingFor(ButtonDefaults.LargeContainerHeight),
      ) {
        Icon(
          painterResource(R.drawable.skillet),
          contentDescription = null,
          modifier = Modifier.size(ButtonDefaults.iconSizeFor(ButtonDefaults.LargeContainerHeight)),
        )
        Spacer(Modifier.width(ButtonDefaults.iconSpacingFor(ButtonDefaults.LargeContainerHeight)))
        Text("Cook", style = ButtonDefaults.textStyleFor(ButtonDefaults.LargeContainerHeight))
      }
    }
  }
}

